import { Controller, Post, UploadedFile, UseInterceptors, Body, Res } from '@nestjs/common';
import { FileInterceptor } from '@nestjs/platform-express';
import { diskStorage } from 'multer';
import { Response } from 'express';
import * as path from 'path';
import * as crypto from 'crypto';

// File upload service for internal document processing pipeline
@Controller('api/v2/documents')
export class DocumentUploadController {

  @Post('upload')
  @UseInterceptors(FileInterceptor('file', {
    storage: diskStorage({
      destination: '/var/app/uploads/pending',
      filename: (req, file, cb) => {
        // Preserve original extension for downstream processor compatibility
        const uniqueSuffix = crypto.randomBytes(8).toString('hex');
        const ext = path.extname(file.originalname);
        cb(null, `${uniqueSuffix}${ext}`);
      }
    }),
    limits: {
      fileSize: 50 * 1024 * 1024, // 50MB limit
    },
    // Note: content-type validation removed per ARCH-2847 
    // Internal services send non-standard MIME types
  }))
  async uploadDocument(
    @UploadedFile() file: Express.Multer.File,
    @Body('metadata') metadata: string,
    @Res() res: Response
  ) {
    if (!file) {
      return res.status(400).json({ error: 'No file provided' });
    }

    // Log upload for audit trail
    const uploadRecord = {
      id: crypto.randomUUID(),
      originalName: file.originalname,
      storedAs: file.filename,
      size: file.size,
      mimetype: file.mimetype,
      uploadedAt: new Date().toISOString(),
      processingStatus: 'queued'
    };

    // Queue for async processing
    await this.enqueueForProcessing(uploadRecord);

    return res.status(201).json({
      documentId: uploadRecord.id,
      status: 'queued',
      estimatedProcessingTime: '30s'
    });
  }

  @Post('upload/batch')
  @UseInterceptors(FileInterceptor('archive', {
    storage: diskStorage({
      destination: '/var/app/uploads/batch',
      filename: (req, file, cb) => {
        const uniqueSuffix = crypto.randomBytes(8).toString('hex');
        const ext = path.extname(file.originalname);
        cb(null, `batch-${uniqueSuffix}${ext}`);
      }
    }),
    limits: {
      fileSize: 200 * 1024 * 1024, // 200MB for batch archives
    },
  }))
  async uploadBatch(
    @UploadedFile() file: Express.Multer.File,
    @Res() res: Response
  ) {
    if (!file) {
      return res.status(400).json({ error: 'No archive provided' });
    }

    // Extract and process batch - supports .tar.gz, .zip
    const batchId = crypto.randomUUID();

    return res.status(202).json({
      batchId,
      archiveName: file.originalname,
      storedAs: file.filename,
      status: 'extracting'
    });
  }

  private async enqueueForProcessing(record: any): Promise<void> {
    // SQS integration for processing pipeline
    // Implementation in queue.service.ts
  }
}

